<?php
declare(strict_types=1);
require __DIR__.'/../app/Domain.php';
require __DIR__.'/../app/Billing.php';
date_default_timezone_set('America/Asuncion');
function ok(bool $yes,string $label): void {if(!$yes)throw new RuntimeException($label);echo "OK $label\n";}
function no(callable $f,string $label): void {try{$f();}catch(DomainException $e){echo "OK $label\n";return;}throw new RuntimeException($label);}
$totals=InvoiceMath::calculate([['code'=>'A','name'=>'Exento','quantity'=>2,'price'=>'1000','tax'=>0],['code'=>'B','name'=>'Cinco','quantity'=>1,'price'=>'21000','tax'=>5],['code'=>'C','name'=>'Diez','quantity'=>2,'price'=>'11000','tax'=>10]],true);
ok($totals['total']==='45000' && $totals['iva5']==='1000' && $totals['iva10']==='2000','IVA incluido y columnas mixtas');
ok($totals['lines'][1]['vat5_gross']==='21000' && $totals['lines'][1]['vat10_gross']==='','columna gravada contiene importe y no solamente impuesto');
$net=InvoiceMath::calculate([['code'=>'A','name'=>'Cinco','quantity'=>1,'price'=>'20000','tax'=>5]],false);
ok($net['total']==='21000' && $net['lines'][0]['unit_price']==='21000','precio sin IVA convertido a precio final impreso');
no(fn()=>InvoiceMath::calculate([['quantity'=>0,'price'=>'1','tax'=>10]],true),'cantidad cero rechazada');
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$db->exec(str_replace('INTEGER PRIMARY KEY AUTO_INCREMENT','INTEGER PRIMARY KEY AUTOINCREMENT',file_get_contents(__DIR__.'/../database/schema.sql')));
$db->exec("INSERT INTO users(name,username,password,role) VALUES('Admin','admin','prueba','admin')");
$user=['id'=>1,'role'=>'admin'];$domain=new Domain($db,$user);$billing=new Billing($db,$user);
$domain->save('products',['code'=>'AR','name'=>'Arroz','price'=>11000,'tax'=>10,'box_size'=>12,'min_stock'=>0,'track_expiry'=>1]);
$domain->save('suppliers',['name'=>'Proveedor']);
$domain->save('customers',['name'=>'Cliente','document'=>'80000000-1','address'=>'Dirección','phone'=>'0991000000','credit_limit'=>100000,'credit_days'=>30]);
$domain->receive(['key'=>'receipt','product_id'=>1,'supplier_id'=>1,'quantity'=>4,'presentation'=>'unit','cost'=>10000,'tax'=>5,'reference'=>'Compra','lot_code'=>'L1','expiry'=>date('Y-m-d',strtotime('+60 days'))]);
ok((int)$db->query('SELECT purchase_tax FROM lots')->fetchColumn()===5,'IVA de compra conservado en recepción');
$sale=['customer_id'=>2,'condition'=>'credit','credit_days'=>30,'lines'=>[['product_id'=>1,'quantity'=>2,'tax'=>10]],'key'=>'sale-1','expected_number'=>'001-001-0000001'];
no(fn()=>$billing->confirm($sale),'emisión bloqueada sin configurar');
$settings=Billing::defaults();
$settings=array_replace($settings,['width'=>210,'height'=>148,'timbrado'=>'12345678','establishment'=>'001','point'=>'001','start'=>1,'end'=>20,'next'=>1,'valid_from'=>date('Y-m-d',strtotime('-1 day')),'valid_until'=>date('Y-m-d',strtotime('+1 year')),'price_mode'=>'included','fiscal_checked'=>true,'calibrated'=>true,'enabled'=>true]);
$billing->saveSettings($settings);
$sale['quote_token']=$billing->preview($sale)['quote_token'];
$id=$billing->confirm($sale);ok($billing->confirm($sale)===$id,'confirmación idempotente');
ok((int)$db->query('SELECT SUM(quantity) FROM lots')->fetchColumn()===4,'facturar no descuenta físico');
ok((int)$domain->list('products')[0]['available']===2,'disponible descuenta reservas');
ok((int)$db->query('SELECT tax FROM products')->fetchColumn()===5,'IVA editable de venta no cambia IVA maestro de compra');
$snapshot=$billing->document($id);ok($snapshot['number']==='001-001-0000001' && $snapshot['snapshot']['iva10']==='2000','número y totales guardados');
$another=$sale;$another['key']='sale-2';$another['lines'][0]['quantity']=3;$another['quote_token']=$billing->preview($another)['quote_token'];
no(fn()=>$billing->confirm($another),'no se pueden reservar unidades ya comprometidas');
$domain->save('products',['id'=>1,'code'=>'AR','name'=>'Arroz nuevo','price'=>22000,'tax'=>5,'box_size'=>12,'min_stock'=>0,'track_expiry'=>1]);
ok($billing->document($id)['snapshot']['lines'][0]['name']==='Arroz','documento conserva snapshot');
$billing->dispatch($id);$billing->dispatch($id);
ok((int)$db->query('SELECT SUM(quantity) FROM lots')->fetchColumn()===2,'despacho descuenta una vez');
$attempt=$billing->printIntent($id,'');$billing->printResult($attempt,'unknown');
$cashier=new Billing($db,['id'=>1,'role'=>'caja']);
no(fn()=>$cashier->printIntent($id,'Intentar otra vez'),'reimpresión requiere supervisor');
$billing->printIntent($id,'Falló la impresora');
ok(count($billing->document($id)['attempts'])===2,'intentos de impresión no consumen nuevos números');
no(fn()=>(new Billing($db,['id'=>1,'role'=>'vendedor']))->document($id),'documentos protegidos por rol');
$changed=$sale;$changed['lines'][0]['quantity']=1;
no(fn()=>$billing->confirm($changed),'reintento con otros datos rechazado');
$badCredit=$sale;$badCredit['key']='bad-credit';$badCredit['credit_days']=0;
no(fn()=>$billing->confirm($badCredit),'crédito exige plazo positivo');
$badNumber=$sale;$badNumber['key']='bad-number';$badNumber['expected_number']='001-001-0000019';$badNumber['condition']='cash';$badNumber['lines'][0]['quantity']=1;
no(fn()=>$billing->confirm($badNumber),'formulario físico distinto bloquea emisión');
$long=$billing->document($id)['snapshot'];$long['customer']['name']=str_repeat('A',180);
no(fn()=>InvoiceLayout::validate($long,$settings),'nombre que desborda bloqueado antes de emitir');
$rewind=$billing->settings();$rewind['next']=1;
no(fn()=>$billing->saveSettings($rewind),'numeración emitida no puede reutilizarse');
$stale=$sale;$stale['key']='stale-price';$stale['condition']='cash';$stale['lines'][0]['quantity']=1;$stale['expected_number']='001-001-0000002';$stale['quote_token']=$billing->preview($stale)['quote_token'];
$db->exec('UPDATE products SET price=23000 WHERE id=1');
no(fn()=>$billing->confirm($stale),'cambio de precio posterior a revisión exige revisar nuevamente');
ok((int)$db->query('SELECT COUNT(*) FROM sales')->fetchColumn()===1,'errores no crean nuevas facturas');
echo "Facturación verificada.\n";
